#pragma once
#include "kstationFlashStateTask.h"
namespace kstation {
class StartupSchedulerTask final {
public:enum class Stage {Clear,PublishClear,PublishCallback,PublishDelay,ReadTick,PublishTick,Return,Complete};enum class Write{Clear,Callback,Delay,Tick};StartupSchedulerTask(unsigned slot=0,bool arm=false,uint32_t callback=0,uint16_t delay=0):stage_(arm?Stage::PublishCallback:Stage::Clear),slot_(slot),callback_(callback),delay_(delay),armed_(arm){}bool armed()const{return armed_;}Stage stage()const{return stage_;}bool complete()const{return stage_==Stage::Complete;}unsigned slot()const{return slot_;}bool awaiting()const{return waiting_;}void resume(uint16_t tick){tick_=tick;waiting_=false;}
 unsigned nextClocks(const FlashCredits&c)const{if(waiting_||complete())return 0;switch(stage_){case Stage::PublishClear:case Stage::PublishDelay:case Stage::PublishTick:return 9+c.write;case Stage::PublishCallback:return 12+c.write;case Stage::ReadTick:return c.call;case Stage::Return:return c.ret;default:return 3;}}
 template<class W>unsigned advanceBefore(unsigned budget,const FlashCredits&c,W&&write){auto cost=nextClocks(c);if(!cost||cost>budget)return 0;auto next=Stage(unsigned(stage_)+1);switch(stage_){case Stage::PublishClear:write(Write::Clear,0);next=Stage::Return;break;case Stage::PublishCallback:write(Write::Callback,callback_);break;case Stage::PublishDelay:write(Write::Delay,delay_);break;case Stage::ReadTick:waiting_=true;break;case Stage::PublishTick:write(Write::Tick,tick_);break;default:break;}stage_=next;return cost;}
private:Stage stage_;unsigned slot_;uint32_t callback_;uint16_t delay_,tick_=0;bool waiting_=false,armed_=false;};
class StartupClockTask final {
public:enum class Stage {Delay,Callback,Schedule,Return,Complete};Stage stage()const{return stage_;}bool complete()const{return stage_==Stage::Complete;}bool awaiting()const{return waiting_;}void resume(){waiting_=false;}unsigned nextClocks(const FlashCredits&c)const{return waiting_||complete()?0:stage_==Stage::Delay?6:stage_==Stage::Callback?9:stage_==Stage::Schedule?c.call:c.ret;}unsigned advanceBefore(unsigned budget,const FlashCredits&c){auto cost=nextClocks(c);if(!cost||cost>budget)return 0;if(stage_==Stage::Schedule)waiting_=true;stage_=Stage(unsigned(stage_)+1);return cost;}
private:Stage stage_=Stage::Delay;bool waiting_=false;};
class StartupAdcReadTask final {
public:enum class Stage {Retain,Clear,Select,Double,Bind,Read,Subtract,SelectClamp,Clamp,Publish,Restore,Return,Complete};explicit StartupAdcReadTask(uint8_t channel=0):channel_(channel){}Stage stage()const{return stage_;}bool complete()const{return stage_==Stage::Complete;}unsigned offset()const{return uint8_t(channel_*2);}uint8_t result()const{return uint8_t(value_>>8);}unsigned nextClocks(const FlashCredits&c)const{switch(stage_){case Stage::Retain:return c.pushLong;case Stage::Bind:return 9;case Stage::Read:return 3+c.read;case Stage::Subtract:return 6;case Stage::Restore:return c.popLong;case Stage::Return:return c.ret;case Stage::Complete:return 0;default:return 3;}}
 template<class R>unsigned advanceBefore(unsigned budget,const FlashCredits&c,R&&read){auto cost=nextClocks(c);if(!cost||cost>budget)return 0;auto next=Stage(unsigned(stage_)+1);switch(stage_){case Stage::Read:value_=uint16_t(read());break;case Stage::Subtract:under_=value_<256;value_=uint16_t(value_-256);break;case Stage::SelectClamp:if(!under_)next=Stage::Publish;break;case Stage::Clamp:value_=0;break;default:break;}stage_=next;return cost;}
private:Stage stage_=Stage::Retain;uint8_t channel_;uint16_t value_=0;bool under_=false;};
class StartupVolumeTask final {
public:enum class Stage {Retain,ReadInput,Square,Double,RetainGain,ClearFraction,Address,Send,Restore,Return,Complete};explicit StartupVolumeTask(uint8_t volume=0):volume_(volume){}Stage stage()const{return stage_;}bool complete()const{return stage_==Stage::Complete;}bool awaiting()const{return waiting_;}void resume(){waiting_=false;}uint32_t word()const{return uint32_t(gain_)<<8;}unsigned nextClocks(const FlashCredits&c)const{if(waiting_||complete())return 0;switch(stage_){case Stage::Retain:return c.pushWord;case Stage::Square:return 15;case Stage::Address:return 6;case Stage::Send:return c.call;case Stage::Restore:return c.popWord;case Stage::Return:return c.ret;default:return 3;}}
 unsigned advanceBefore(unsigned budget,const FlashCredits&c){auto cost=nextClocks(c);if(!cost||cost>budget)return 0;switch(stage_){case Stage::Square:gain_=uint16_t(volume_*volume_);break;case Stage::Double:gain_=uint16_t(gain_*2);break;case Stage::Send:waiting_=true;break;default:break;}stage_=Stage(unsigned(stage_)+1);return cost;}
private:Stage stage_=Stage::Retain;uint8_t volume_;uint16_t gain_=0;bool waiting_=false;};
class StartupArpStateTask final {
public:enum class Stage {Clear,PublishFlags,PublishNote,PublishPhase,ReadPeriod,PublishPeriod,Return,Complete};enum class Write{Flags,Note,Phase,Period};Stage stage()const{return stage_;}bool complete()const{return stage_==Stage::Complete;}unsigned nextClocks(const FlashCredits&c)const{switch(stage_){case Stage::PublishFlags:case Stage::PublishNote:return 9+c.write;case Stage::PublishPhase:case Stage::PublishPeriod:return 12+c.write;case Stage::ReadPeriod:return 12+c.read;case Stage::Return:return c.ret;case Stage::Complete:return 0;default:return 3;}}
 template<class R,class W>unsigned advanceBefore(unsigned budget,const FlashCredits&c,R&&read,W&&write){auto cost=nextClocks(c);if(!cost||cost>budget)return 0;switch(stage_){case Stage::PublishFlags:write(Write::Flags,0);break;case Stage::PublishNote:write(Write::Note,0);break;case Stage::PublishPhase:write(Write::Phase,0);break;case Stage::ReadPeriod:period_=read();break;case Stage::PublishPeriod:write(Write::Period,period_);break;default:break;}stage_=Stage(unsigned(stage_)+1);return cost;}
private:Stage stage_=Stage::Clear;uint32_t period_=0;};
}
